.root {
  --vt-surface: #ffffff;
  --vt-surface-2: #fffafa;
  --vt-surface-deep: #1e1e1e;
  --vt-ink: #2a2a2a;
  --vt-ink-soft: #5f5f5f;
  --vt-on-deep: #ffffff;
  --vt-accent: #fb5849;
  --vt-on-accent: #1a1a1a;
  --vt-accent-ink: #c73e30;
  --vt-accent-on-deep: #ff8f84;
  --vt-line: #e5e5e5;

  --vt-font-body: 'Manrope', 'Fira Sans', sans-serif;
  --vt-font-display: 'Fraunces', 'Noto Serif Display', serif;

  font-family: var(--vt-font-body);
  color: var(--vt-ink);
  background: var(--vt-surface);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  width: 100%;
  max-width: 100%;
  overflow-x: clip;
}

.root *,
.root *::before,
.root *::after {
  box-sizing: border-box;
}

.root :where(a) {
  color: inherit;
  text-decoration: none;
}

.root :where(h1, h2, h3, h4, h5, h6) {
  margin: 0;
  font-weight: 700;
}

.root :where(p) {
  margin: 0;
}

.root img {
  display: block;
  max-width: 100%;
}

.root a:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 3px;
}

/* Nav */
.root .nav {
  position: sticky;
  top: 0;
  z-index: 20;
  background: var(--vt-surface);
  border-bottom: 1px solid var(--vt-line);
}

.root .navIn {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
  height: 76px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  min-width: 0;
}

.root .logo {
  display: flex;
  align-items: center;
}

.root .brand {
  font-size: 1.35rem;
  font-weight: 800;
  color: var(--vt-ink);
  letter-spacing: 0.5px;
}

.root .navLinks {
  display: flex;
  gap: 32px;
}

.root .navLinks a {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--vt-ink);
  transition: color 0.2s ease;
}

.root .navLinks a:hover {
  color: var(--vt-accent);
}

/* Hero */
.root .hero {
  display: flex;
  min-height: 640px;
  background: var(--vt-surface-2);
}

.root .heroLeft {
  flex: 0 0 34%;
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  padding: 64px 48px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 18px;
}

.root .heroKicker {
  text-transform: uppercase;
  letter-spacing: 3px;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--vt-accent-on-deep);
}

.root .heroTitle {
  font-family: var(--vt-font-display);
  font-size: clamp(2.5rem, 5vw, 4rem);
  line-height: 1.1;
  color: var(--vt-on-deep);
}

.root .heroTag {
  font-size: 1.05rem;
  color: var(--vt-on-deep);
  opacity: 0.85;
  max-width: 34ch;
}

.root .heroButton {
  align-self: flex-start;
  display: inline-block;
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  padding: 14px 32px;
  border-radius: 40px;
  font-weight: 700;
  font-size: 0.95rem;
  transition: transform 0.2s ease, border-color 0.2s ease;
  border: 1px solid var(--vt-accent);
}

.root .heroButton:hover {
  transform: translateY(-2px);
  border-color: var(--vt-on-accent);
}

.root .heroSlider {
  flex: 1;
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
}

.root .heroSlider::-webkit-scrollbar {
  display: none;
}

.root .heroSlide {
  flex: 0 0 100%;
  min-width: 100%;
  scroll-snap-align: start;
  position: relative;
}

.root .heroSlide img {
  width: 100%;
  height: 100%;
  min-height: 640px;
  object-fit: cover;
}

.root .heroNoMedia .heroLeft {
  flex: 1;
  text-align: center;
  align-items: center;
}

.root .heroNoMedia .heroButton {
  align-self: center;
}

/* Shared section kicker */
.root .kicker {
  text-transform: uppercase;
  letter-spacing: 2px;
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--vt-accent);
  display: inline-block;
  margin-bottom: 12px;
}

/* About */
.root .about {
  max-width: 1200px;
  margin: 0 auto;
  padding: 100px 24px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.root .aboutText h2 {
  font-family: var(--vt-font-display);
  font-size: 2.2rem;
  line-height: 1.2;
  margin-bottom: 20px;
}

.root .aboutText p {
  color: var(--vt-ink-soft);
  margin-bottom: 16px;
}

.root .aboutMedia {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.root .aboutMain img {
  width: 100%;
  height: 460px;
  object-fit: cover;
  border-radius: 8px;
}

.root .aboutThumbs {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  margin-left: 32px;
  margin-top: -48px;
  position: relative;
}

.root .aboutThumbs img {
  width: 100%;
  height: 100px;
  object-fit: cover;
  border-radius: 6px;
  border: 4px solid var(--vt-surface);
}

/* Services / menu */
.root .services {
  background: var(--vt-surface-2);
  padding: 100px 24px;
}

.root .sectionHead {
  max-width: 1200px;
  margin: 0 auto 60px;
  text-align: center;
}

.root .sectionHead .kicker {
  color: var(--vt-accent);
}

.root .sectionHead h2 {
  font-family: var(--vt-font-display);
  font-size: 2.2rem;
}

.root .menuTrack {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 24px;
}

.root .menuCard {
  background: var(--vt-surface);
  border-radius: 8px;
  overflow: hidden;
  position: relative;
  box-shadow: 0 2px 8px var(--vt-line);
}

.root .menuImg {
  width: 100%;
  height: 260px;
  object-fit: cover;
}

.root .menuBody {
  padding: 24px;
  position: static;
}

.root .menuNum {
  position: absolute;
  top: 16px;
  right: 16px;
  z-index: 2;
  width: 52px;
  height: 52px;
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 1.1rem;
}

.root .menuBody h3 {
  font-size: 1.2rem;
  margin: 8px 0;
}

.root .menuBody p {
  color: var(--vt-ink-soft);
  font-size: 0.95rem;
}

/* Gallery */
.root .gallery {
  max-width: 1200px;
  margin: 0 auto;
  padding: 100px 24px;
}

.root .galleryGrid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.root .galleryItem {
  position: relative;
  border-radius: 8px;
  overflow: hidden;
  aspect-ratio: 4 / 3;
}

.root .galleryItem img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}

.root .galleryItem:hover img {
  transform: scale(1.04);
}

.root .galleryItem figcaption {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  padding: 16px 20px;
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
}

.root .galleryItem figcaption h3 {
  font-size: 1rem;
  margin-bottom: 4px;
}

.root .galleryItem figcaption p {
  font-size: 0.85rem;
  opacity: 0.8;
  color: var(--vt-on-deep);
}

/* Contact */
.root .contact {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  padding: 100px 24px;
}

.root .contactInner {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr;
  gap: 48px;
  align-items: start;
}

.root .contactInfo .kicker {
  color: var(--vt-accent-on-deep);
}

.root .contactInfo h2 {
  font-family: var(--vt-font-display);
  font-size: 2.2rem;
  margin-bottom: 16px;
}

.root .contactInfo p {
  color: var(--vt-on-deep);
  opacity: 0.85;
}

.root .contactList {
  margin: 24px 0;
  display: grid;
  gap: 12px;
}

.root .contactList div {
  display: flex;
  gap: 12px;
}

.root .contactList dt {
  font-weight: 700;
  min-width: 90px;
}

.root .contactList dd {
  color: var(--vt-on-deep);
  opacity: 0.85;
}

.root .contactCard {
  background: var(--vt-surface);
  color: var(--vt-ink);
  border-radius: 8px;
  padding: 32px;
  width: 100%;
  min-width: 0;
  min-height: 320px;
}

/* Footer */
.root .footer {
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  padding: 32px 24px;
}

.root .footerInner {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.root .footer p {
  color: var(--vt-on-accent);
}

/* Responsive */
@media (max-width: 992px) {
  .root .hero {
    flex-direction: column;
  }

  .root .heroLeft {
    flex: 1;
    padding: 48px 24px;
    text-align: center;
    align-items: center;
  }

  .root .heroButton {
    align-self: center;
  }

  .root .heroNoMedia .heroButton {
    align-self: center;
  }

  .root .heroSlider {
    width: 100%;
  }

  .root .heroSlide img {
    min-height: 360px;
  }

  .root .about {
    grid-template-columns: 1fr;
    gap: 48px;
  }

  .root .aboutThumbs {
    margin-left: 0;
    margin-top: 12px;
  }

  .root .contactInner {
    grid-template-columns: 1fr;
    gap: 48px;
  }

  .root .galleryGrid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 640px) {
  .root .navLinks {
    display: none;
  }

  .root .menuTrack {
    grid-template-columns: 1fr;
  }

  .root .galleryGrid {
    grid-template-columns: 1fr;
  }

  .root .footerInner {
    flex-direction: column;
    gap: 8px;
    text-align: center;
  }
}
